<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, ref, watch } from 'vue'
import PdfComposer from './PdfComposer.vue'
import SystemSettings from './SystemSettings.vue'
import BatchBrowser from './BatchBrowser.vue'
import { Folder, Inbox, CalendarDays, Files, Trash2, Search, Upload, Grid2X2, List, RotateCcw, RotateCw, Download, X, ChevronLeft, ChevronRight, LogOut, Settings2, FileText, Check, ScanLine, RefreshCw, ZoomIn, ZoomOut, Maximize, Undo2 } from 'lucide-vue-next'
type Scan = { batch_id:string|null;id:string; name:string; mime:string; size:number; uploaded_at:number; device:string; qr:string; rotation:number; width:number|null; height:number|null; deleted_at:number|null }
const pdfFiles=ref<Scan[]|null>(null), batchId=ref(''), batchName=ref(''), revision=ref(0)
const authenticated=ref(false), csrf=ref(''), username=ref('admin'), password=ref(''), error=ref(''), notice=ref(''), busy=ref(false)
const items=ref<Scan[]>([]), total=ref(0), selected=ref(new Set<string>()), anchor=ref(0), page=ref(0), loading=ref(false)
const section=ref('inbox'), q=ref(''), kind=ref(''), device=ref(''), date=ref(''), sort=ref(localStorage.getItem('sort')||'newest'), view=ref(localStorage.getItem('view')||'grid'), thumb=ref(Number(localStorage.getItem('thumb'))||190)
const theme=ref(localStorage.getItem('theme')||'system'), uploadInput=ref<HTMLInputElement|null>(null)
const info=ref({count:0,bytes:0,trash_bytes:0,free_bytes:0,devices:[] as string[],device_profiles:[] as {source:string;label:string;location:string}[]}), preview=ref<Scan|null>(null), zoom=ref(1), fit=ref(true), connected=ref(false)
let source:EventSource|null=null, searchTimer:ReturnType<typeof setTimeout>, generation=0, pendingRefresh=false
const title=computed(()=>({inbox:'最近扫描',today:'今日扫描',all:'全部文件',trash:'回收站',batches:'扫描批次',settings:'系统设置'}[section.value]))
const allImages=computed(()=>selected.value.size>0 && [...selected.value].every(id=>items.value.find(f=>f.id===id)?.mime.startsWith('image/')))
const bytes=(n:number)=>{const units=['B','KB','MB','GB','TB'];let i=0;while(n>=1024&&i<units.length-1){n/=1024;i++}return `${i?n.toFixed(1):n} ${units[i]}`}
const deviceLabel=(source:string)=>info.value.device_profiles?.find(p=>p.source===source)?.label||source
const timestamp=(n:number)=>new Date(n*1000).toLocaleString('zh-CN',{month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'})
const url=(f:Scan,route:string)=>`/api/files/${f.id}/${route}?r=${f.rotation}`
async function api(path:string, options:RequestInit={}) {
 const response=await fetch(path,{...options,headers:{'X-CSRF-Token':csrf.value,...options.headers}})
 if(!response.ok){let message='操作失败';try{const data=await response.json();message=typeof data.detail==='string'?data.detail:'请求格式错误'}catch{} if(response.status===401){authenticated.value=false;source?.close()} throw new Error(message)}
 return response
}
async function login(){busy.value=true;error.value='';try{const response=await api('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({username:username.value,password:password.value})});csrf.value=(await response.json()).csrf;password.value='';authenticated.value=true;await loadDefaults();await refresh();events()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function logout(){try{await api('/api/auth/logout',{method:'POST'});authenticated.value=false;source?.close();preview.value=null;items.value=[];selected.value.clear()}catch(e){error.value=(e as Error).message}}
async function refresh(){
 const ticket=++generation;loading.value=true
 try{const params=new URLSearchParams({q:q.value,kind:kind.value,device:device.value,sort:sort.value,deleted:String(section.value==='trash'),offset:String(page.value*100),limit:'100',batch:batchId.value})
 let day=date.value;if(section.value==='today'){const now=new Date();day=`${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}-${String(now.getDate()).padStart(2,'0')}`}
 if(day){const from=new Date(day+'T00:00:00');const to=new Date(from);to.setDate(to.getDate()+1);params.set('after',String(from.getTime()/1000));params.set('before',String(to.getTime()/1000))}
 const [listing,stats]=await Promise.all([api('/api/files?'+params).then(r=>r.json()),api('/api/storage').then(r=>r.json())]);if(ticket!==generation)return
 items.value=listing.items;total.value=listing.total;info.value=stats;revision.value++
 if(preview.value){const replacement=items.value.find(i=>i.id===preview.value?.id);if(replacement)preview.value=replacement}
 }catch(e){error.value=(e as Error).message}finally{if(ticket===generation)loading.value=false}
}
function events(){source?.close();source=new EventSource('/api/events');source.onopen=()=>connected.value=true;source.onerror=()=>connected.value=false;source.onmessage=()=>{if(busy.value)pendingRefresh=true;else void refresh()};source.addEventListener('expired',()=>{authenticated.value=false;source?.close()})}
function changeSection(value:string){section.value=value;batchId.value='';batchName.value='';page.value=0;selected.value=new Set();void refresh()}
function choose(f:Scan,index:number,event:MouseEvent){const next=new Set(selected.value);if(event.shiftKey){const start=Math.min(anchor.value,index),end=Math.max(anchor.value,index);for(let i=start;i<=end;i++)next.add(items.value[i]!.id)}else if(event.ctrlKey||event.metaKey){next.has(f.id)?next.delete(f.id):next.add(f.id);anchor.value=index}else{next.clear();next.add(f.id);anchor.value=index}selected.value=next}
function toggle(id:string){const next=new Set(selected.value);next.has(id)?next.delete(id):next.add(id);selected.value=next}
function selectAll(){selected.value=selected.value.size===items.value.length?new Set():new Set(items.value.map(f=>f.id))}
async function action(which:string,ids=[...selected.value]){if(!ids.length)return;if(which==='delete'&&!confirm(`将 ${ids.length} 个文件移入回收站？可随时恢复。`))return;busy.value=true;error.value='';try{await api('/api/files/batch',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ids,action:which})});notice.value=which==='left'?'已向左旋转 90°，原始文件已保留':which==='right'?'已向右旋转 90°，原始文件已保留':which==='restore'?'已恢复文件':'已移入回收站';if(which==='delete'||which==='restore')selected.value=new Set();await refresh()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function downloadZip(){const name=prompt('ZIP 文件名','扫描文件.zip');if(!name)return;busy.value=true;try{const response=await api('/api/files/zip',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ids:[...selected.value],name})});const link=document.createElement('a');link.href=URL.createObjectURL(await response.blob());link.download=name.endsWith('.zip')?name:name+'.zip';link.click();setTimeout(()=>URL.revokeObjectURL(link.href),30000)}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function upload(event:Event){const input=event.target as HTMLInputElement;if(!input.files?.length)return;const form=new FormData();for(const f of input.files)form.append('paper',f);form.append('device','浏览器上传');busy.value=true;error.value='';try{const result=await (await api('/api/upload',{method:'POST',body:form})).json();notice.value=`已接收 ${result.files.length} 个文件`+(result.files.some((f:{duplicate_of:string|null})=>f.duplicate_of)?'，检测到重复内容，所有文件均已保留':'');await refresh()}catch(e){error.value=(e as Error).message}finally{busy.value=false;input.value=''}}
async function loadDefaults(){try{applyDefaults(await (await api('/api/settings')).json())}catch(e){error.value=(e as Error).message}}
function applyDefaults(data:Record<string,any>){sort.value=data.default_sort;view.value=data.default_view;thumb.value=data.thumbnail_size}
function openBatch(id:string,name:string){section.value='all';batchId.value=id;batchName.value=name;page.value=0;selected.value=new Set();void refresh()}
async function batchPdf(id:string){try{const result=await(await api('/api/files?batch='+encodeURIComponent(id)+'&limit=200&sort=oldest')).json();if(result.total>200)throw new Error('批次超过 200 张图片，请进入批次后分批选择');if(!result.items.length||result.items.some((f:Scan)=>!f.mime.startsWith('image/')))throw new Error('此批次包含 PDF 或非图片文件，请进入批次后只选择图片');pdfFiles.value=result.items}catch(e){error.value=(e as Error).message}}
async function organize(){const name=prompt('新批次名称（选中文件将移动到此手动批次）','手动整理批次');if(!name?.trim())return;busy.value=true;try{await api('/api/batches/organize',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ids:[...selected.value],name})});notice.value='已将选中文件移动到新批次';selected.value=new Set();await refresh()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function permanentDelete(all:boolean){if(!confirm(all?'永久删除整个回收站中的全部文件？此操作无法恢复。':`永久删除选中的 ${selected.value.size} 个文件？此操作无法恢复。`))return;busy.value=true;try{const result=await(await api(all?'/api/trash/empty':'/api/trash/purge',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({ids:[...selected.value],confirm:'PERMANENT_DELETE'})})).json();notice.value=`已永久删除 ${result.deleted} 个文件`+(result.pending?'，部分磁盘清理将在后台重试':'');selected.value=new Set();await refresh()}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
const dialog=ref<HTMLDialogElement|null>(null)
async function openPreview(f:Scan){preview.value=f;zoom.value=1;fit.value=true;await nextTick();dialog.value?.showModal()}
function closePreview(){dialog.value?.close();preview.value=null}
function navigate(delta:number){if(!preview.value)return;const i=items.value.findIndex(f=>f.id===preview.value?.id);const f=items.value[i+delta];if(f){preview.value=f;zoom.value=1;fit.value=true}}
function keydown(e:KeyboardEvent){if((e.target as HTMLElement)?.matches('input,textarea,select'))return;if(preview.value){if(e.key==='ArrowLeft')navigate(-1);if(e.key==='ArrowRight')navigate(1);return}if(!authenticated.value)return;if(e.key==='/'){e.preventDefault();document.querySelector<HTMLInputElement>('.search input')?.focus()}if((e.ctrlKey||e.metaKey)&&e.key==='a'){e.preventDefault();selectAll()}if(e.key==='Escape')selected.value=new Set()}
function turnPage(delta:number){page.value+=delta;selected.value=new Set();void refresh()}
const grid=ref<HTMLElement|null>(null), box=ref<{x:number,y:number,w:number,h:number}|null>(null)
let start:{x:number,y:number,original:Set<string>}|null=null
function dragStart(e:PointerEvent){if(e.pointerType!=='mouse'||e.button!==0||e.target!==grid.value)return;start={x:e.clientX,y:e.clientY,original:e.ctrlKey||e.metaKey?new Set(selected.value):new Set()};grid.value?.setPointerCapture(e.pointerId)}
function dragMove(e:PointerEvent){if(!start)return;const left=Math.min(start.x,e.clientX),top=Math.min(start.y,e.clientY),w=Math.abs(start.x-e.clientX),h=Math.abs(start.y-e.clientY);box.value={x:left,y:top,w,h};const next=new Set(start.original);grid.value?.querySelectorAll<HTMLElement>('[data-id]').forEach(el=>{const r=el.getBoundingClientRect();if(r.right>left&&r.left<left+w&&r.bottom>top&&r.top<top+h)next.add(el.dataset.id!)});selected.value=next}
function dragEnd(){start=null;box.value=null}
watch([q,kind,device,date,sort],()=>{clearTimeout(searchTimer);searchTimer=setTimeout(()=>{page.value=0;selected.value=new Set();void refresh()},250)})
watch(busy,value=>{if(!value&&pendingRefresh){pendingRefresh=false;void refresh()}})
watch([sort,view,thumb,theme],()=>{localStorage.setItem('sort',sort.value);localStorage.setItem('view',view.value);localStorage.setItem('thumb',String(thumb.value));localStorage.setItem('theme',theme.value);document.documentElement.dataset.theme=theme.value})
onMounted(async()=>{document.documentElement.dataset.theme=theme.value;window.addEventListener('keydown',keydown);try{const r=await fetch('/api/auth/session');if(r.ok){csrf.value=(await r.json()).csrf;authenticated.value=true;await loadDefaults();await refresh();events()}}catch{error.value='无法连接 ScanHub 服务'}})
onUnmounted(()=>{source?.close();clearTimeout(searchTimer);window.removeEventListener('keydown',keydown)})
</script>

<template>
 <div v-if="!authenticated" class="login-shell"><form class="login" @submit.prevent="login"><ScanLine :size="38" class="brand-icon"/><h1>ScanHub</h1><p>让每一页扫描，都井然有序。</p><label>管理员账号<input v-model="username" autocomplete="username" required></label><label>密码<input v-model="password" type="password" autocomplete="current-password" required></label><p v-if="error" class="error" role="alert">{{error}}</p><button class="primary" :disabled="busy">{{busy?'正在登录…':'登录工作空间'}}</button><small>自托管 · 局域网扫描文件管理</small></form></div>
 <div v-else class="workspace">
  <header class="topbar"><a class="brand" href="/" aria-label="ScanHub 首页"><ScanLine :size="26"/>ScanHub<span>工作空间</span></a><label class="search"><Search :size="18"/><input v-model="q" aria-label="搜索文件名或二维码" placeholder="搜索文件名或二维码…"><kbd>/</kbd></label><span class="service"><i :class="{online:connected}"></i>{{connected?'实时更新已连接':'正在重新连接'}}</span><button title="系统设置" aria-label="系统设置" @click="changeSection('settings')"><Settings2 :size="19"/></button><button title="退出登录" aria-label="退出登录" @click="logout"><LogOut :size="19"/></button></header>
  <aside class="sidebar"><div class="nav-caption">资料库</div><nav><button :class="{active:section==='inbox'}" @click="changeSection('inbox')"><Inbox :size="19"/>收件箱</button><button :class="{active:section==='today'}" @click="changeSection('today')"><CalendarDays :size="19"/>今日扫描</button><button :class="{active:section==='all'}" @click="changeSection('all')"><Files :size="19"/>全部文件</button><button :class="{active:section==='batches'}" @click="changeSection('batches')"><Folder :size="19"/>扫描批次</button><button :class="{active:section==='trash'}" @click="changeSection('trash')"><Trash2 :size="19"/>回收站</button></nav><div class="sidebar-bottom"><span class="nav-caption">本地存储</span><strong>{{bytes(info.bytes)}}</strong><small>{{info.count}} 个文件 · 剩余 {{bytes(info.free_bytes)}}</small><p>扫描仪主动上传<br>原件保留至主动清理</p></div></aside>
  <main>
   <div class="heading"><div><div class="eyebrow">{{section==='trash'?'可恢复的文件':'你的纸质资料，已在这里'}} </div><h1>{{batchName||title}}<span v-if="!['settings','batches'].includes(section)">{{total}}</span></h1><p>{{section==='trash'?'文件仍保存在本地，选择后可恢复。':'浏览、整理和下载来自扫描仪的文件。'}}</p></div><button v-if="section!=='settings'" class="primary" :disabled="busy" @click="uploadInput?.click()"><Upload :size="17"/>上传文件</button><input ref="uploadInput" class="hidden" type="file" multiple accept=".jpg,.jpeg,.png,.tif,.tiff,.pdf" @change="upload"></div>
   <section v-if="section==='settings'" class="settings" aria-label="显示设置"><label>外观<select v-model="theme"><option value="system">跟随系统</option><option value="light">浅色</option><option value="dark">深色</option></select></label><label>缩略图大小<input v-model="thumb" type="range" min="150" max="300"></label><p>批量旋转为非破坏性操作。ZIP 与“下载原件”保留原始方向；JPG/PNG 可在预览中下载方向修正图片。</p></section>
   <p v-if="error" class="banner error" role="alert">{{error}}<button aria-label="关闭错误" @click="error='' "><X :size="16"/></button></p><p v-if="notice" class="banner success" role="status"><Check :size="17"/>{{notice}}<button aria-label="关闭提示" @click="notice='' "><X :size="16"/></button></p>
   <SystemSettings v-if="section==='settings'" :csrf="csrf" @saved="applyDefaults"/><BatchBrowser v-else-if="section==='batches'" :csrf="csrf" :revision="revision" @open="openBatch" @pdf="batchPdf" @changed="refresh"/><template v-else><div v-if="batchId" class="batch-context"><span>当前批次：{{batchName}}</span><button @click="changeSection('batches')">返回全部批次</button></div><div class="filters"><label>类型<select v-model="kind"><option value="">全部类型</option><option value="image/jpeg">JPEG</option><option value="image/png">PNG</option><option value="image/tiff">TIFF</option><option value="application/pdf">PDF</option></select></label><label>来源<select v-model="device"><option value="">全部设备</option><option v-for="d in info.devices" :key="d" :value="d">{{deviceLabel(d)}}</option></select></label><label v-if="section!=='today'">日期<input v-model="date" aria-label="上传日期" type="date"></label><label class="sort">排序<select v-model="sort"><option value="newest">最新上传</option><option value="oldest">最早上传</option><option value="name">文件名称</option><option value="size">文件大小</option></select></label><div class="view-toggle"><button :class="{active:view==='grid'}" aria-label="网格视图" :aria-pressed="view==='grid'" @click="view='grid'"><Grid2X2 :size="18"/></button><button :class="{active:view==='list'}" aria-label="列表视图" :aria-pressed="view==='list'" @click="view='list'"><List :size="18"/></button></div></div>
   <div class="actionbar"><button v-if="section==='trash'" class="danger" :disabled="busy" @click="permanentDelete(true)">清空回收站</button><label class="select-all"><input type="checkbox" :checked="items.length>0&&selected.size===items.length" @change="selectAll">本页全选</label><span class="selection-count">{{selected.size?'已选 '+selected.size+' 个文件':'选择文件进行批量操作'}}</span><template v-if="selected.size"><button :disabled="busy" @click="downloadZip"><Download :size="17"/>原件 ZIP</button><template v-if="section!=='trash'"><button :disabled="busy||!allImages" @click="pdfFiles=items.filter(f=>selected.has(f.id))"><FileText :size="17"/>合并 PDF</button><button :disabled="busy" @click="organize">拆分 / 归类</button><button :disabled="busy||!allImages" title="选中图片全部左旋 90°，保留原件" @click="action('left')"><RotateCcw :size="17"/>左旋 90°</button><button :disabled="busy||!allImages" title="选中图片全部右旋 90°，保留原件" @click="action('right')"><RotateCw :size="17"/>右旋 90°</button><button class="danger" :disabled="busy" @click="action('delete')"><Trash2 :size="17"/>移入回收站</button></template><template v-else><button :disabled="busy" @click="action('restore')"><Undo2 :size="17"/>恢复</button><button class="danger" :disabled="busy" @click="permanentDelete(false)">永久删除</button></template><button aria-label="取消选择" @click="selected=new Set()"><X :size="17"/></button></template><button v-else class="refresh" :disabled="loading" @click="refresh"><RefreshCw :size="16"/>刷新</button></div>
   <div v-if="!items.length" class="empty"><Inbox :size="46"/><h2>{{loading?'正在读取文件…':'这里还没有扫描文件'}}</h2><p>{{q||kind||device||date?'尝试调整搜索或筛选条件。':'从扫描仪上传，或点击“上传文件”开始。'}}</p></div>
   <div v-else ref="grid" :class="['file-area',view]" :style="{'--thumb':thumb+'px'}" @pointerdown="dragStart" @pointermove="dragMove" @pointerup="dragEnd" @pointercancel="dragEnd">
    <article v-for="(file,index) in items" :key="file.id" :data-id="file.id" :class="['file',{'selected':selected.has(file.id)}]" @click="choose(file,index,$event)" @dblclick="openPreview(file)">
     <div class="paper"><input type="checkbox" :aria-label="'选择 '+file.name" :checked="selected.has(file.id)" @click.stop @change="toggle(file.id)"><img v-if="file.mime!=='application/pdf'" :src="url(file,'thumbnail')" :alt="file.name" loading="lazy" draggable="false"><div v-else class="pdf-icon"><FileText :size="42"/><span>PDF</span></div><span v-if="file.rotation" class="rotation-badge">{{file.rotation}}°</span><button class="preview-button" @click.stop="openPreview(file)">预览</button></div><div class="file-meta"><button class="file-name" @click.stop="openPreview(file)" :title="file.name">{{file.name}}</button><div class="meta-line"><span>{{timestamp(file.uploaded_at)}}</span><span>{{bytes(file.size)}}</span></div><div class="source-line">{{deviceLabel(file.device)}}<span v-if="file.qr" title="包含二维码信息"> · QR</span></div></div><a class="list-download" :href="url(file,'original')" @click.stop aria-label="下载原件"><Download :size="18"/></a>
    </article>
   </div>
   <footer class="pagination"><span>共 {{total}} 个文件 · 当前显示 {{items.length}} 个</span><div><button :disabled="page===0||loading" aria-label="上一页" @click="turnPage(-1)"><ChevronLeft :size="18"/></button><span>第 {{page+1}} 页</span><button :disabled="(page+1)*100>=total||loading" aria-label="下一页" @click="turnPage(1)"><ChevronRight :size="18"/></button></div></footer></template>
  </main>
  <PdfComposer v-if="pdfFiles" :files="pdfFiles" :csrf="csrf" @close="pdfFiles=null"/><div v-if="box" class="selection-box" :style="{left:box.x+'px',top:box.y+'px',width:box.w+'px',height:box.h+'px'}"></div>
  <dialog ref="dialog" class="preview-dialog" @cancel.prevent="closePreview"><template v-if="preview"><header><div><strong>{{preview.name}}</strong><small>{{preview.device}} · {{bytes(preview.size)}} · {{preview.rotation}}°</small></div><button aria-label="关闭预览" @click="closePreview"><X/></button></header><p v-if="error" class="banner error" role="alert">{{error}}</p><div class="preview-toolbar"><button aria-label="上一个文件" @click="navigate(-1)"><ChevronLeft :size="19"/></button><button aria-label="下一个文件" @click="navigate(1)"><ChevronRight :size="19"/></button><template v-if="preview.mime!=='application/pdf'"><button aria-label="缩小" @click="fit=false;zoom=Math.max(.1,zoom-.25)"><ZoomOut :size="19"/></button><span>{{fit?'适应窗口':Math.round(zoom*100)+'%'}}</span><button aria-label="放大" @click="fit=false;zoom=Math.min(4,zoom+.25)"><ZoomIn :size="19"/></button><button @click="fit=true"><Maximize :size="17"/>适应</button><button @click="fit=false;zoom=1">100%</button><button :disabled="busy||!!preview.deleted_at" @click="action('left',[preview.id])"><RotateCcw :size="17"/>左旋</button><button :disabled="busy||!!preview.deleted_at" @click="action('right',[preview.id])"><RotateCw :size="17"/>右旋</button></template><a :href="url(preview,'original')"><Download :size="17"/>下载原件</a><a v-if="['image/jpeg','image/png'].includes(preview.mime)" :href="url(preview,'rotated')">下载方向修正 PNG</a></div><div class="preview-content"><iframe v-if="preview.mime==='application/pdf'" :src="url(preview,'preview')" title="PDF 多页预览" sandbox="allow-same-origin"></iframe><div v-else class="image-canvas"><img :src="url(preview,'preview')" :alt="preview.name" :class="{fit}" :style="fit?{}:{width:((preview.rotation%180?preview.height:preview.width)||1000)*zoom+'px',maxWidth:'none',maxHeight:'none'}"></div></div><footer class="preview-details"><span>{{timestamp(preview.uploaded_at)}} · {{preview.mime}}<template v-if="preview.width"> · {{preview.width}} × {{preview.height}}</template><template v-if="preview.mime==='image/tiff'"> · TIFF 预览仅显示首页</template></span><p v-if="preview.qr">二维码：{{preview.qr}}</p></footer></template></dialog>
 </div>
</template>
